/*
 * LotteryUpdateController.kt
 * Purpose: Owner lottery-editing rules and orchestration for US 02.04.06.
 * Preserves the document identity, ownership, waiting list, and draw state.
 * Registration start locks once registration opens. Included campsites and stay
 * dates lock while entrants are waiting. All edits stop when registration ends.
 * Persistence repeats these checks against current records inside a transaction.
 */


package com.example.code.controller

import com.example.code.data.LotteryUpdateRepository
import com.example.code.model.Campsite
import com.example.code.model.Lottery
import com.example.code.model.LotteryCampsite

object LotteryUpdateController {
    /** Whether configuration editing can still be offered for this lottery. */
    fun canEdit(lottery: Lottery, now: Long): Boolean =
        lottery.status == Lottery.STATUS_OPEN && now < lottery.registrationEnd

    /**
     * Compares configuration while permitting concurrent waitlist joins/leaves.
     * Two editors cannot silently overwrite each other's changed settings.
     */
    fun sameConfiguration(first: Lottery, second: Lottery): Boolean =
        first.copy(waitingListCount = 0, winnerIds = emptyList()) ==
                second.copy(waitingListCount = 0, winnerIds = emptyList())

    /** Produces a validated update using actual owned campsite records. */
    fun prepareUpdate(
        current: Lottery,
        ownerId: String,
        campsites: List<Campsite>,
        settings: Lottery,
        now: Long,
    ): Lottery {
        require(current.id.isNotBlank() && '/' !in current.id && current.id != "." && current.id != "..") {
            "A saved lottery is required."
        }
        require(ownerId.isNotBlank() && current.ownerId == ownerId) {
            "You can only update your own lotteries."
        }
        require(canEdit(current, now)) {
            "This lottery cannot be edited after registration closes or winners are drawn."
        }
        require(campsites.isNotEmpty()) { "Select at least one campsite." }
        // Other owners' campsites already in a shared lottery can stay, but only your own can be added
        require(campsites.all { it.ownerId == ownerId || LotteryController.includesCampsite(current, it.id) }) {
            "You can only select your own campsites."
        }
        require(campsites.map { it.id }.distinct().size == campsites.size) {
            "A campsite cannot be selected more than once."
        }
        val references = campsites.map { LotteryCampsite(it.id, it.name) }
        val proposed = current.copy(
            campsiteId = references.first().id,
            campsiteName = references.first().name,
            campsites = if (references.size > 1) references else emptyList(),
            registrationStart = settings.registrationStart,
            registrationEnd = settings.registrationEnd,
            bookingStart = settings.bookingStart,
            bookingEnd = settings.bookingEnd,
            winnerCount = settings.winnerCount,
            waitlistCapacity = settings.waitlistCapacity,
        )
        LotteryController.validateCreation(proposed)
        require(proposed.registrationEnd > now) { "Registration must end in the future." }
        if (now >= current.registrationStart) {
            require(proposed.registrationStart == current.registrationStart) {
                "Registration has opened, so its start time cannot change."
            }
        }
        if (current.waitingListCount > 0) {
            require(
                references.map { it.id }.toSet() ==
                        LotteryController.includedCampsites(current).map { it.id }.toSet(),
            ) { "Included campsites cannot change while entrants are on the waiting list." }
            require(proposed.bookingStart == current.bookingStart && proposed.bookingEnd == current.bookingEnd) {
                "Stay dates cannot change while entrants are on the waiting list."
            }
        }
        require(proposed.waitlistCapacity == null || proposed.waitlistCapacity >= current.waitingListCount) {
            "Waiting-list capacity cannot be below the number of entrants already joined."
        }
        return proposed
    }

    /** Transaction-time validation using the latest lottery and campsite records. */
    fun revalidate(
        original: Lottery,
        current: Lottery,
        ownerId: String,
        campsites: List<Campsite>,
        settings: Lottery,
        now: Long,
    ): Lottery {
        require(current.id == original.id) { "The lottery identity changed. Reopen the editor." }
        require(ownerId.isNotBlank() && current.ownerId == ownerId) {
            "You can only update your own lotteries."
        }
        require(canEdit(current, now)) {
            "This lottery cannot be edited after registration closes or winners are drawn."
        }
        require(sameConfiguration(original, current)) {
            "This lottery was updated elsewhere. Reopen the editor to load its latest settings."
        }
        return prepareUpdate(current, ownerId, campsites, settings, now)
    }

    /** Validates early for the form; the repository revalidates before saving. */
    suspend fun updateLottery(
        repository: LotteryUpdateRepository,
        original: Lottery,
        ownerId: String,
        campsites: List<Campsite>,
        settings: Lottery,
        clock: () -> Long = System::currentTimeMillis,
    ) {
        val proposed = prepareUpdate(original, ownerId, campsites, settings, clock())
        repository.updateLottery(original, ownerId, proposed)
    }
}
